    while ($pos < $data_len) {
        my ($offset, $length) = find_matches($input_text, $pos, 31, 7);

        if (defined $offset) {
            # Back-reference
            push @operations, ['ref', $offset - 1, $length - 1];
            $pos += $length;
        } else {
            # Literal
            my $char_val = ord(substr($input_text, $pos, 1));
            if ($char_val > 127) {
