use strict;
use warnings;

# Minimal encoder to test basic protocol
# Goal: encode just "Hi" (2 literals) to verify arithmetic coding works

my $RADIX = 255;
my $OFF1 = 5;
my $OFF2 = 2; 
my $LITSIZE = 4;

my @output;
my $low = 0;
my $range = 1;  # Match decoder initialization
my %counts;

sub output_byte {
    my ($val) = @_;
    $val = 255 if $val > 255;
    $val = 1 if $val < 1;
    push @output, $val;
}

sub normalize {
    while ($range < $RADIX) {
        my $val = int($low / $RADIX) + 1;
        output_byte($val);
        $low = ($low % $RADIX) * $RADIX;
        $range *= $RADIX;
    }
}

sub put_bit {
    my ($bit, $ctx) = @_;
    normalize();

    $counts{$ctx} = [0, 0] unless exists $counts{$ctx};
    my $c = $counts{$ctx};

    my $split = int($range * ($c->[0] + 1) / ($c->[0] + $c->[1] + 2));

    if ($bit) {
        $low += $split;
        $range -= $split;
        $c->[1]++;
    } else {
        $range = $split;
